BEGIN TRANSACTION;
DROP TABLE IF EXISTS "aktivasi_bku";
CREATE TABLE [aktivasi_bku] (
  [id_anggaran] varchar(22) NOT NULL, 
  [id_periode] numeric(2,0) NOT NULL, 
  [tanggal_aktivasi] datetime NOT NULL, 
  [tanggal_finish] datetime, 
  [saldo_awal_bank] money, 
  [saldo_awal_tunai] money, 
  [saldo_akhir_bank] money, 
  [saldo_akhir_tunai] money, 
  [saldo_awal_bank_sisa] money, 
  [saldo_awal_tunai_sisa] money, 
  [saldo_akhir_bank_sisa] money, 
  [saldo_akhir_tunai_sisa] money, 
  [soft_delete] numeric(1,0) NOT NULL DEFAULT 0, 
  [create_date] datetime NOT NULL, 
  [last_update] datetime NOT NULL, 
  [updater_id] varchar(22) NOT NULL, status_pengiriman numeric(1) default 0, 
  CONSTRAINT [sqlite_autoindex_aktivasi_bku_1] PRIMARY KEY ([id_anggaran], [id_periode]));
DROP TABLE IF EXISTS "anggaran";
CREATE TABLE anggaran (
  id_anggaran varchar(22) NOT NULL, 
  id_ref_sumber_dana numeric(2,0) NOT NULL, 
  sekolah_id varchar(22) NOT NULL, 
  volume numeric(6,0), 
  harga_satuan money, 
  jumlah money, 
  sisa_anggaran money, 
  is_pengesahan numeric(1,0) DEFAULT 0, 
  tanggal_pengajuan datetime, 
  tanggal_pengesahan datetime, 
  is_approve numeric(1,0) NOT NULL DEFAULT 0, 
  is_revisi numeric(3,0) NOT NULL DEFAULT 0, 
  alasan_penolakan varchar(4000), 
  is_aktif numeric(1,0) NOT NULL DEFAULT 0, 
  tahun_anggaran numeric(4,0) NOT NULL DEFAULT 0, 
  soft_delete numeric(1,0) NOT NULL DEFAULT 0, 
  create_date datetime NOT NULL, 
  last_update datetime NOT NULL, 
  updater_id varchar(22), 
  id_penjab varchar(22), 
  CONSTRAINT CKC_IS_APPROVE_ANGGARAN CHECK(is_approve in (0,1,2)), 
  CONSTRAINT sqlite_autoindex_anggaran_1 PRIMARY KEY (id_anggaran)
);
DROP TABLE IF EXISTS "anggaran_sumber_dana";
CREATE TABLE `anggaran_sumber_dana` (     id_anggaran_sumber_dana VARCHAR (22)   NOT NULL,     id_anggaran        VARCHAR (22)   NOT NULL,     nama_pemberi           VARCHAR (50),     jumlah           MONEY          NOT NULL,     soft_delete      NUMERIC (1, 0) NOT NULL                                     DEFAULT 0,     create_date      DATETIME       NOT NULL,     last_update      DATETIME       NOT NULL,     updater_id       VARCHAR (22),     CONSTRAINT PK_ANGGARAN_SUMBER_DANA PRIMARY KEY (         id_anggaran_sumber_dana     ) );
DROP TABLE IF EXISTS "app";
CREATE TABLE app (
   app_id               varchar(22)                 not null,
   nama                 varchar(80)          not null,
   url_login            varchar(255)         not null,
   url_post             varchar(255)         not null,
   login_info           varchar(500)         null,
   tag                  int                  not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_APP primary key (app_id)
);
DROP TABLE IF EXISTS "app_config";
CREATE TABLE app_config (
   varname              varchar(50)          not null,
   varvalue             varchar(255)         not null,
   constraint PK_APP_CONFIG primary key (varname)
);
DROP TABLE IF EXISTS "app_log";
CREATE TABLE app_log (     app_log_id  varchar(22)  not null         constraint app_log_id_primary_key             primary key,     log_type    varchar(255) not null,     context     varchar(255),     message     text,     stack       text,     endpoint    varchar(500),     status_code integer,     params      text,     request     text,     response    text,     create_date datetime default current_timestamp );
DROP TABLE IF EXISTS "config_anggaran";
CREATE TABLE config_anggaran (
   sekolah_id           guid                 not null,
   id_ref_sumber_dana   numeric(2,0)         not null,
   is_allow_create      numeric(1,0)         not null,
   is_allow_revisi      numeric(1,0)         not null,
   is_block_bku         numeric(1,0)         not null,
   keterangan           varchar(2000)        null,
   constraint PK_CONFIG_ANGGARAN primary key (sekolah_id, id_ref_sumber_dana)
);
DROP TABLE IF EXISTS "indikator";
CREATE TABLE indikator (
   id_indikator         varchar(22)                 not null,
   id_ref_indikator     numeric(2,0)         not null,
   id_rka               varchar(22)                 null,
   tolak_ukur           varchar(2000)        null,
   capaian              varchar(2000)        null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 not null,
   constraint PK_INDIKATOR primary key (id_indikator)
);
DROP TABLE IF EXISTS "instansi";
CREATE TABLE instansi (
   instansi_id          varchar(22)                 not null,
   ins_instansi_id      varchar(22)                 null,
   jenis_instansi_id    numeric(2,0)         not null,
   kode_instansi        char(8)              null,
   nama                 varchar(80)          not null,
   alamat               varchar(50)          not null,
   kode_pos             int                  null,
   kode_wilayah         char(8)              not null,
   lintang              decimal(10,6)        null default null,
   bujur                decimal(10,6)        null default null,
   email                varchar(50)          null,
   telepon              varchar(20)          null,
   fax                  varchar(20)          null,
   website              varchar(50)          null,
   tag                  int                  null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 not null,
   constraint PK_INSTANSI primary key (instansi_id)
);
DROP TABLE IF EXISTS "instansi_pengguna";
CREATE TABLE instansi_pengguna (
   instansi_pengguna_id varchar(22)                 not null,
   pengguna_id          varchar(22)                 not null,
   instansi_id          varchar(22)                 not null,
   jabatan_id           numeric(6,0)         not null,
   sk                   varchar(150)         not null,
   tanggal_sk           datetime             null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 not null,
   constraint PK_INSTANSI_PENGGUNA primary key (instansi_pengguna_id)
);
DROP TABLE IF EXISTS "kas_umum";
CREATE TABLE [kas_umum] (
  [id_kas_umum] varchar(22) NOT NULL, 
  [id_kas_nota] varchar(22), 
  [id_rapbs_periode] varchar(22), 
  [kode_rekening] varchar(20), 
  [id_ref_bku] int NOT NULL, 
  [id_anggaran] varchar(22) NOT NULL, 
  [parent_id_kas_umum] varchar(22), 
  [tanggal_transaksi] datetime NOT NULL, 
  [no_bukti] varchar(30), 
  [uraian] varchar(500) NOT NULL, 
  [uraian_pajak] varchar(255), 
  [saldo] money NOT NULL, 
  [status_bku] char(1), 
  [volume] numeric(6,0), 
  [is_ppn] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_21] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_22] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_23] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_4] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_sspd] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_lock] numeric(1,0), 
  [tanggal_lock] datetime, 
  [soft_delete] numeric(1,0) NOT NULL DEFAULT 0, 
  [create_date] datetime NOT NULL, 
  [last_update] datetime NOT NULL, 
  [updater_id] varchar(22) NULL, 
  CONSTRAINT [sqlite_autoindex_kas_umum_1] PRIMARY KEY ([id_kas_umum]));
DROP TABLE IF EXISTS "kas_umum_nota";
CREATE TABLE kas_umum_nota (     id_kas_nota       VARCHAR (22),     no_bukti          VARCHAR (30),     tanggal_nota      DATE,     no_nota           VARCHAR (255),     nama_toko         VARCHAR (255),     alamat_toko       VARCHAR (2000),     no_telp           VARCHAR (25),     is_badan_usaha    NUMERIC (1),     npwp              VARCHAR (20),     total             NUMERIC,     kode_rekening     VARCHAR (20),     id_ref_kode       VARCHAR (22),     has_ppn           NUMERIC (1),     has_pph_22        NUMERIC (1),     create_date       DATETIME,     last_update       DATETIME,     soft_delete       NUMERIC (1),     updater_id        VARCHAR (22),     alasan_pecah_nota TEXT (1000),     is_beli_di_siplah NUMERIC (1)    DEFAULT 0,     details           TEXT,     CONSTRAINT sqlite_autoindex_kas_umum_nota_1 PRIMARY KEY (         id_kas_nota     ) );
DROP TABLE IF EXISTS "kas_umum_nota_pajak";
CREATE TABLE kas_umum_nota_pajak  (      id_kas_nota   VARCHAR(22)          NOT NULL,      ntpn          VARCHAR(16)          NOT NULL,      tanggal_lapor DATETIME,      soft_delete   NUMERIC(1) DEFAULT 0 NOT NULL,      create_date   DATETIME             NOT NULL,      last_update   DATETIME             NOT NULL,      updater_id    VARCHAR(22)          NOT NULL,      CONSTRAINT kas_umum_nota_pajak_pk          UNIQUE (id_kas_nota, ntpn)  );
DROP TABLE IF EXISTS "kas_umum_temp";
CREATE TABLE [kas_umum_temp] (
  [id_kas_umum] varchar(22) NOT NULL, 
  [id_kas_nota] varchar(22), 
  [id_rapbs_periode] varchar(22), 
  [kode_rekening] varchar(20), 
  [id_ref_bku] int NOT NULL, 
  [id_anggaran] varchar(22) NOT NULL, 
  [parent_id_kas_umum] varchar(22), 
  [tanggal_transaksi] datetime NOT NULL, 
  [no_bukti] varchar(30), 
  [uraian] varchar(500) NOT NULL, 
  [uraian_pajak] varchar(255), 
  [saldo] money NOT NULL, 
  [status_bku] char(1), 
  [volume] numeric(6,0), 
  [is_ppn] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_21] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_22] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_23] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_pph_4] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_sspd] numeric(1,0) NOT NULL DEFAULT 0, 
  [is_lock] numeric(1,0), 
  [tanggal_lock] datetime, 
  [soft_delete] numeric(1,0) NOT NULL DEFAULT 0, 
  [create_date] datetime NOT NULL, 
  [last_update] datetime NOT NULL, 
  [updater_id] varchar(22) NULL, 
  CONSTRAINT [sqlite_autoindex_kas_umum_temp_1] PRIMARY KEY ([id_kas_umum]));
DROP TABLE IF EXISTS "manage_app";
CREATE TABLE manage_app (
   manage_id            varchar(22)                 not null,
   pengguna_id          varchar(22)                 not null,
   app_id               varchar(22)                 not null,
   is_superadmin        bit                  null,
   constraint PK_MANAGE_APP primary key (manage_id)
);
DROP TABLE IF EXISTS "migrations";
CREATE TABLE migrations (   index_executed_sql_file numeric PRIMARY KEY,   executed_sql_file varchar(255) not null,   create_date datetime not null );
DROP TABLE IF EXISTS "mst_sekolah";
CREATE TABLE [mst_sekolah] (
  [sekolah_id] varchar(22) NOT NULL, 
  [kode_wilayah] char(8) NOT NULL, 
  [nama] varchar(80), 
  [npsn] char(8) NOT NULL, 
  [alamat] varchar(50) NOT NULL, 
  [status_sekolah] numeric(1) NOT NULL, 
  [bentuk_pendidikan_id] smallint NOT NULL, 
  [telepon] varchar(20), 
  [kepsek] varchar(80) NOT NULL, 
  [telepon_kepsek] varchar(20), 
  [nip_kepsek] varchar(20), 
  [email_kepsek] varchar(30), 
  [tu] varchar(80), 
  [telepon_tu] varchar(20), 
  [nip_tu] varchar(20), 
  [email_tu] varchar(30), 
  [jumlah_siswa] numeric(4), 
  [kode_registrasi] varchar(10), 
  [soft_delete] numeric(1,0) NOT NULL DEFAULT 0, 
  [create_date] datetime NOT NULL, 
  [last_update] datetime NOT NULL, 
  [updater_id] varchar(22) NOT NULL, 
  CONSTRAINT [sqlite_autoindex_mst_sekolah_1] PRIMARY KEY ([sekolah_id]));
DROP TABLE IF EXISTS "mst_wilayah";
CREATE TABLE mst_wilayah (
   kode_wilayah         char(8)              not null,
   mst_kode_wilayah     char(8)              null,
   negara_id            char(2)              not null,
   id_level_wilayah     smallint             not null,
   nama                 varchar(80)          not null,
   asal_wilayah         char(8)              null,
   kode_bps             char(7)              null,
   kode_dagri           char(7)              null,
   kode_keu             varchar(10)          null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_MST_WILAYAH primary key (kode_wilayah)
);
DROP TABLE IF EXISTS "pengesahan";
CREATE TABLE pengesahan (
   id_pengesahan        varchar(22)                 not null,
   id_rapbs             varchar(22)                 not null,
   id_anggaran          varchar(22)                 not null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   exp_updater_id       varchar(22)                 not null,
   is_sah               numeric(1,0)         null,
   updater_id           varchar(22)                 null,
   constraint PK_PENGESAHAN primary key (id_pengesahan)
);
DROP TABLE IF EXISTS "pengguna";
CREATE TABLE pengguna (
   pengguna_id          varchar(22)                 not null,
   nama                 varchar(80)          not null,
   tempat_lahir         varchar(50)          not null,
   tanggal_lahir        datetime             not null,
   jenis_kelamin        char(1)              not null,
   alamat               varchar(50)          null,
   kode_pos             int                  null,
   telepon              varchar(20)          null,
   show_telepon         numeric(1)           null constraint DF_pegawai_status_hp default (1),
   nip                  varchar(50)          null,
   kode_wilayah         char(8)              null,
   email                varchar(50)          not null,
   password             varchar(32)          not null,
   forgot_pass1         varchar(50)          null,
   forgot_pass2         varchar(50)          null,
   status_approval      numeric(1)           not null default 0,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 not null,
   constraint PK_PENGGUNA primary key (pengguna_id)
);
DROP TABLE IF EXISTS "ptk";
CREATE TABLE [ptk] (
  [sekolah_id] varchar(22) NOT NULL, 
  [ptk_id] varchar(22) NOT NULL, 
  [tahun_ajaran_id] int NOT NULL, 
  [nama] varchar(80) NOT NULL, 
  [jenis_kelamin] char(1) NOT NULL, 
  [masa_kerja_tahun] int NOT NULL, 
  [masa_kerja_bulan] int NOT NULL, 
  [nuptk] varchar(16) NULL,
  [jenis_ptk_arkas] int NOT NULL, 
  [pernah_serfikasi] int NOT NULL,
  [is_cut_off] int NOT NULL, 
  [create_date] datetime NOT NULL, 
  [last_update] datetime NOT NULL, 
  [soft_delete] int NOT NULL, 
  CONSTRAINT [] PRIMARY KEY ([sekolah_id], [ptk_id], [tahun_ajaran_id]) ON CONFLICT ROLLBACK
);
DROP TABLE IF EXISTS "rapbs";
CREATE TABLE "rapbs" (     id_rapbs              varchar(22)          not null         constraint sqlite_autoindex_rapbs_1             primary key,     sekolah_id            varchar(22)          not null,     id_anggaran           varchar(22)          not null,     id_ref_kode           varchar(22)          not null,     id_ref_tahun_anggaran numeric(4)           not null,     kode_rekening         varchar(20)          not null,     id_barang             varchar(40),     urutan                varchar(5),     uraian                varchar(500)         not null,     uraian_text           varchar(255),     volume                numeric(6)           not null,     satuan                varchar(30)          not null,     harga_satuan          money                not null,     jumlah                money                not null,     v1                    numeric(6),     s1                    varchar(30),     v2                    numeric(6),     s2                    varchar(30),     v3                    numeric(6),     s3                    varchar(30),     v4                    numeric(6),     s4                    varchar(30),     keterangan            varchar(2000),     soft_delete           numeric(1) default 0 not null,     create_date           datetime             not null,     last_update           datetime             not null,     updater_id            varchar(22) );
DROP TABLE IF EXISTS "rapbs_periode";
CREATE TABLE rapbs_periode ( 
   id_rapbs_periode     varchar(22)                 not null,
   id_rapbs             varchar(22)                 not null,
   id_periode           numeric(2,0)         not null,
   volume               numeric(6,0)         not null,
   satuan               varchar(30)          not null,
   harga_satuan         money                not null,
   jumlah               money                not null,
   v1                   numeric(6,0)         null,
   s1                   varchar(30)          null,
   v2                   numeric(6,0)         null,
   s2                   varchar(30)          null,
   v3                   numeric(6,0)         null,
   s3                   varchar(30)          null,
   v4                   numeric(6,0)         null,
   s4                   varchar(30)          null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 null,
   constraint PK_RAPBS_PERIODE primary key (id_rapbs_periode)
);
DROP TABLE IF EXISTS "rapbs_ptk";
CREATE TABLE [rapbs_ptk] (
  [id_rapbs] varchar(22) not null, 
  [ptk_id] varchar(22) not null,   
  [nama] varchar(80) null,
  [create_date] datetime not null, 
  [last_update] datetime not null, 
  CONSTRAINT [] PRIMARY KEY ([id_rapbs], [ptk_id]));
DROP TABLE IF EXISTS "ref_acuan_barang";
CREATE TABLE "ref_acuan_barang"
            (
                id_barang     varchar(40)  not null,
                kode_rekening varchar(20),
                nama_barang   varchar(255) not null,
                satuan        varchar(30),
                blok_id       varchar(6)   not null,
                kode_belanja  varchar(4),
                harga_barang  money,
                batas_bawah   money,
                batas_atas    money,
                kategori_id   varchar(20),
                hs_code       varchar(20),
                kbki          varchar(20),
                create_date   datetime     not null,
                last_update   datetime     not null,
                expired_date  datetime,
                tahun         integer      not null,
                constraint sqlite_autoindex_ref_acuan_barang_id_barang_tahun_1
                    primary key (id_barang, tahun)
            );
DROP TABLE IF EXISTS "ref_bku";
CREATE TABLE [ref_bku] (
  [id_ref_bku] int NOT NULL, 
  [bku] varchar(30) NOT NULL, 
  [kode_bku] varchar(5) NOT NULL, 
  [create_date] datetime NOT NULL, 
  [last_update] datetime NOT NULL, 
  [expired_date] datetime, 
  CONSTRAINT [sqlite_autoindex_ref_bku_1] PRIMARY KEY ([id_ref_bku]));
DROP TABLE IF EXISTS "ref_bulan";
CREATE TABLE ref_bulan (
   id_bulan             numeric(2,0)         not null,
   id_periode           numeric(2,0)         not null,
   bulan                varchar(20)          not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_BULAN primary key (id_bulan)
);
DROP TABLE IF EXISTS "ref_indikator";
CREATE TABLE ref_indikator (
   id_ref_indikator     numeric(2,0)         not null,
   nama_indikator       varchar(255)         not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_INDIKATOR primary key (id_ref_indikator)
);
DROP TABLE IF EXISTS "ref_jabatan";
CREATE TABLE ref_jabatan (
   jabatan_id           numeric(6,0)         not null,
   ref_jabatan_id       numeric(6,0)         null,
   nama                 varchar(80)          not null,
   level_jabatan        int                  null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_JABATAN primary key (jabatan_id)
);
DROP TABLE IF EXISTS "ref_jenis_instansi";
CREATE TABLE ref_jenis_instansi (
   jenis_instansi_id    numeric(2,0)         not null,
   nama                 varchar(80)          null,
   sort                 int                  null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_JENIS_INSTANSI primary key (jenis_instansi_id)
);
DROP TABLE IF EXISTS "ref_kode";
CREATE TABLE "ref_kode" (     id_ref_kode          VARCHAR(22)  NOT NULL,     id_kode              VARCHAR(12)  NOT NULL,     parent_kode          VARCHAR(22),     uraian_kode          VARCHAR(200) NOT NULL,     is_bos_pusat         NUMERIC(1)   NOT NULL,     is_bos_prop          NUMERIC(1)   NOT NULL,     is_bos_kab           NUMERIC(1)   NOT NULL,     is_komite            NUMERIC(1)   NOT NULL,     is_lainnnya          NUMERIC(1)   NOT NULL,     id_level_kode        NUMERIC(2)   NOT NULL,     bentuk_pendidikan_id NUMERIC(2)   NOT NULL,     create_date          DATETIME     NOT NULL,     last_update          DATETIME     NOT NULL,     expired_date         DATETIME,     tahun                INTEGER      NOT NULL,     sumber_dana_id       INTEGER,     tipe                 INTEGER,     CONSTRAINT sqlite_autoindex_ref_kode_id_ref_kode_tahun_1         PRIMARY KEY (id_ref_kode, tahun, sumber_dana_id, bentuk_pendidikan_id) );
DROP TABLE IF EXISTS "ref_level_kode";
CREATE TABLE ref_level_kode (
   id_level_kode        numeric(2,0)         not null,
   nama                 varchar(80)          not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_LEVEL_KODE primary key (id_level_kode)
);
DROP TABLE IF EXISTS "ref_level_wilayah";
CREATE TABLE ref_level_wilayah (
   id_level_wilayah     smallint             not null,
   level_wilayah        varchar(15)          null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_LEVEL_WILAYAH primary key (id_level_wilayah)
);
DROP TABLE IF EXISTS "ref_negara";
CREATE TABLE ref_negara (
   negara_id            char(2)              not null,
   nama                 varchar(80)          not null,
   luar_negeri          boolean              not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_NEGARA primary key (negara_id)
);
DROP TABLE IF EXISTS "ref_pajak";
CREATE TABLE ref_pajak (
   id_ref_pajak         varchar(22)                 not null,
   kode_rekening        varchar(20)          not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   is_ppn               numeric(1,0)         not null default 0,
   is_pph_21            numeric(1,0)         not null default 0,
   is_pph_22            numeric(1,0)         not null default 0,
   is_pph_23            numeric(1,0)         not null default 0,
   is_pph_4             numeric(1,0)         not null default 0,
   constraint PK_REF_PAJAK primary key (id_ref_pajak)
);
DROP TABLE IF EXISTS "ref_periode";
CREATE TABLE ref_periode (
   id_periode           numeric(2,0)         not null,
   periode              varchar(50)          not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_PERIODE primary key (id_periode)
);
DROP TABLE IF EXISTS "ref_rekening";
CREATE TABLE "ref_rekening"
            (
                kode_rekening     varchar(20)          not null,
                rekening          varchar(200)         not null,
                neraca            varchar(200),
                blokid            numeric(2) default 0 not null,
                batas_atas        money,
                batas_bawah       money,
                validasi_type     char(1),
                is_ppn            numeric(1) default 0,
                is_pph21          numeric(1) default 0,
                is_pph22          numeric(1) default 0,
                is_pph23          numeric(1) default 0,
                is_pph4           numeric(1) default 0,
                is_sspd           numeric(1) default 0,
                bhp               char(5),
                is_custom_pajak_1 numeric(1),
                is_honor          numeric(1),
                is_buku           numeric(1),
                is_custom_satuan  numeric(1),
                create_date       datetime             not null,
                last_update       datetime             not null,
                expired_date      datetime,
                tahun             integer              not null,
                constraint sqlite_autoindex_ref_rekening_kode_rekening_tahun_1
                    primary key (kode_rekening, tahun)
            );
DROP TABLE IF EXISTS "ref_rekening_transfer";
CREATE TABLE [ref_rekening_transfer] (
  [kode_rekening_old] VARCHAR(20), 
  [rekening_old] VARCHAR(200), 
  [kode_rekening_new] VARCHAR(20), 
  [rekening_new] VARCHAR(200), 
  [create_date] DATETIME, 
  [last_update] DATETIME);
DROP TABLE IF EXISTS "ref_rekening_transfer_temp";
CREATE TABLE [ref_rekening_transfer_temp] (    [kode_rekening_old] VARCHAR(20),     [rekening_old] VARCHAR(200),     [kode_rekening_new] VARCHAR(20),     [rekening_new] VARCHAR(200),     [create_date] DATETIME,     [last_update] DATETIME);
DROP TABLE IF EXISTS "ref_satuan";
CREATE TABLE ref_satuan (     ref_satuan_id VARCHAR (22) NOT NULL,     satuan        VARCHAR (30) NOT NULL,     unit          VARCHAR (30) NOT NULL,     create_date   DATETIME     NOT NULL,     last_update   DATETIME     NOT NULL,     expired_date  DATETIME,     CONSTRAINT sqlite_autoindex_ref_satuan_1 PRIMARY KEY (         ref_satuan_id     ) );
DROP TABLE IF EXISTS "ref_sumber_dana";
CREATE TABLE ref_sumber_dana (     id_ref_sumber_dana         INTEGER     NOT NULL,     kode                       TEXT        NOT NULL,     nama_sumber_dana           TEXT        NOT NULL,     create_date                DATETIME    NOT NULL,     last_update                DATETIME    NOT NULL,     expired_date               DATETIME,                 is_hidden                  INTEGER     NOT NULL DEFAULT 0,      alias                      TEXT,     jumlah_tahap_pelaporan     INTEGER,     role_pengesahan            INTEGER     NOT NULL DEFAULT 0,     tanggal_akhir_belanja      DATETIME,     tanggal_akhir_laporan      DATETIME,     tanggal_awal_belanja       DATETIME,     tanggal_awal_laporan       DATETIME,     tenggat_penatausahaan      DATETIME,     tenggat_penganggaran       DATETIME,     validasi_anggaran          INTEGER,     is_filtered_by_instansi_id INTEGER     NOT NULL DEFAULT 0,     is_sumber_dana_tambahan    INTEGER     NOT NULL DEFAULT 0, mekanisme_pengesahan integer default 0 not null, is_afirmasi integer default 0 not null,      CONSTRAINT PK_REF_SUMBER_DANA PRIMARY KEY (id_ref_sumber_dana) );
DROP TABLE IF EXISTS "ref_sumber_dana_bentuk_pendidikan";
CREATE TABLE ref_sumber_dana_bentuk_pendidikan(     bentuk_pendidikan_id INTEGER NOT NULL,      id_ref_sumber_dana   INTEGER NOT NULL,      nama                 TEXT    NOT NULL,      create_at            DATETIME NOT NULL,      modify_at            DATETIME NOT NULL,      custom_config        TEXT,                  constraint pk_sumber_dana_bentuk_pendidikan         primary key (id_ref_sumber_dana, bentuk_pendidikan_id) );
DROP TABLE IF EXISTS "ref_sumber_dana_sekolah";
CREATE TABLE ref_sumber_dana_sekolah (     id_ref_sumber_dana INTEGER  NOT NULL,      tahun              INTEGER  NOT NULL,      create_date        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,     last_update        DATETIME,     delete_at          DATETIME,          CONSTRAINT PK_REF_SUMBER_DANA_SEKOLAH PRIMARY KEY (id_ref_sumber_dana, tahun) );
DROP TABLE IF EXISTS "ref_tahun_anggaran";
CREATE TABLE ref_tahun_anggaran (
   id_ref_tahun_anggaran numeric(2,0)         not null,
   tahun_anggaran       varchar(5)           not null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_REF_TAHUN_ANGGARAN primary key (id_ref_tahun_anggaran)
);
DROP TABLE IF EXISTS "rencana_kerja_anggaran";
CREATE TABLE [rencana_kerja_anggaran] (
  [id_rka] varchar(22) NOT NULL, 
  [id_ref_kode] varchar(22) NOT NULL, 
  [instansi_id] varchar(22) NOT NULL, 
  [id_anggaran] varchar(22) NOT NULL, 
  [id_ref_tahun_anggaran] numeric(2,0) NOT NULL, 
  [soft_delete] numeric(1,0) NOT NULL DEFAULT 0, 
  [create_date] datetime NOT NULL, 
  [last_update] datetime NOT NULL, 
  [updater_id] varchar(22) NOT NULL, 
  CONSTRAINT [sqlite_autoindex_rencana_kerja_anggaran_1] PRIMARY KEY ([id_rka]));
DROP TABLE IF EXISTS "report_bku";
CREATE TABLE report_bku (
   id_report_bku        varchar(22)                 not null,
   id_bulan             numeric(2,0)         not null,
   id_anggaran          varchar(22)                 not null,
   id_periode           numeric(2,0)         not null,
   tanggal_buat         datetime             not null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 not null,
   constraint PK_REPORT_BKU primary key (id_report_bku)
);
DROP TABLE IF EXISTS "role";
CREATE TABLE role (
   role_id              varchar(22)                 not null,
   app_id               varchar(22)                 not null,
   nama                 varchar(80)          not null,
   tag                  int                  null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 not null,
   constraint PK_ROLE primary key (role_id)
);
DROP TABLE IF EXISTS "rpt_bku";
CREATE TABLE rpt_bku (
       tanggal_transaksi date not null,       
       id_rapbs_periode varchar(22) null,       
       id_anggaran varchar(22) not null,       
       kode_rekening varchar(20) null,       
       uraian varchar(500) not null,       
       no_bukti varchar(100) null,       
       is_ppn int null,        
       is_pph_21 int null,       
       is_pph_22 int null,       
       is_pph_23 int null,       
       is_pph_4 int null,       
       is_sspd int null,
       id_ref_bku int not null,       
       saldo money not null,       
       create_date datetime not null
);
DROP TABLE IF EXISTS "salur";
CREATE TABLE salur (     sekolah_id                 varchar(22) not null,     npsn                       varchar(22) not null,     tahap                      integer     not null,     gelombang                  smallint    not null default 1,     jenis                      varchar(20) not null,     id_ref_sumber_dana         integer     not null,     nilai_salur_bersih         money       not null,     pengurang_denda_persen     numeric(5, 2),     pengurang_denda_total      money,     pengurang_silpa            money,     pengurang_carry_over       money,     tanggal_disetujui          date,     tidak_terima_dana          numeric(1),     tahun                      integer     not null,     selesai_laporan_tahun_lalu numeric(1),     last_update                datetime    default current_timestamp );
DROP TABLE IF EXISTS "sekolah_history";
CREATE TABLE sekolah_history ( 		sekolah_id varchar(22) NOT NULL, 		tahun integer NOT NULL, 		kode_wilayah char(8) NOT NULL, 		nama varchar(80) NOT NULL, 		status_sekolah numeric(1) NOT NULL, 		bentuk_pendidikan_id smallint NOT NULL, 		create_date datetime NOT NULL, 		last_update datetime NOT NULL, 		PRIMARY KEY (sekolah_id, tahun) 	);
DROP TABLE IF EXISTS "sekolah_penjab";
CREATE TABLE "sekolah_penjab" (     id_penjab VARCHAR (22) NOT NULL,     sekolah_id VARCHAR (22) NOT NULL,     tanggal_mulai DATE NOT NULL,     tanggal_selesai DATE NOT NULL,     ks VARCHAR (50),     nip_ks VARCHAR (20),     email_ks VARCHAR (100),     telp_ks VARCHAR (20),     bendahara VARCHAR (50),     nip_bendahara VARCHAR (20),     email_bendahara VARCHAR (100),     telp_bendahara VARCHAR (20),     komite VARCHAR (50),     nip_komite VARCHAR (100),     soft_delete NUMERIC (1, 0) NOT NULL DEFAULT 0,     create_date DATETIME NOT NULL,     last_update DATETIME NOT NULL,     updater_id VARCHAR (22) NOT NULL,     tahun           integer              NOT NULL,     CONSTRAINT sqlite_autoindex_sekolah_penjab_id_penjab_tahun_1         PRIMARY KEY (id_penjab, tahun) );
DROP TABLE IF EXISTS "status";
CREATE TABLE `status` (     ref_id VARCHAR(100) NOT NULL,     ref_type VARCHAR(100) NOT NULL,     details TEXT(5000) NOT NULL,     create_date DATETIME NOT NULL,     last_update DATETIME NOT NULL,     updater_id VARCHAR(22), soft_delete numeric(1) DEFAULT 0 NOT NULL, CONSTRAINT [sqlite_autoindex_status_1] PRIMARY KEY ([ref_id], [ref_type]) );
DROP TABLE IF EXISTS "tmp_unduh_data";
CREATE TABLE tmp_unduh_data (     api        TEXT         not null,     table_name varchar(255) not null,     tahun      integer      not null,     parameter  TEXT,     data       TEXT,     create_date datetime     not null,     constraint tmp_unduh_data_pk         primary key (api, table_name, tahun) );
DROP TABLE IF EXISTS "token";
CREATE TABLE token (
   token_id             varchar(22)                 not null,
   userrole_id          varchar(22)                 not null,
   app_id               varchar(22)                 not null,
   ipaddr               varchar(30)          null,
   browser              varchar(200)         null,
   create_date          datetime             not null,
   last_update          datetime             not null,
   expired_date         datetime             null,
   constraint PK_TOKEN primary key (token_id)
);
DROP TABLE IF EXISTS "unsend_tracker";
CREATE TABLE `unsend_tracker` (     id           VARCHAR (36)   NOT NULL,     tracker_data TEXT (5000)    NOT NULL,     create_date  DATETIME       NOT NULL,     CONSTRAINT PK_UNSEND_TRACKER PRIMARY KEY (         id     ) );
DROP TABLE IF EXISTS "user_role";
CREATE TABLE user_role (
   userrole_id          varchar(22)                 not null,
   role_id              varchar(22)                 not null,
   instansi_pengguna_id varchar(22)                 not null,
   soft_delete          numeric(1,0)         not null default 0,
   create_date          datetime             not null,
   last_update          datetime             not null,
   updater_id           varchar(22)                 not null,
   constraint PK_USER_ROLE primary key (userrole_id)
);
